// Decodificar JWT del header Authorization
const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) {
  return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
}
const token = auth.slice(7);
try {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('JWT malformed');
  const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub claim');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id || null,
    role: payload.role || 'architect',
    request_id: 'req_' + Math.random().toString(36).slice(2, 10),
    body: $input.first().json.body || $input.first().json
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $input.first().json;
const body = sess.body || {};

// Validar tenant_id presente en JWT (pre-X4 los tokens no lo tenian)
if (!sess.tenant_id) {
  return [{ json: { _error: 'AUTH_NO_TENANT', _status: 403, _details: 'JWT sin tenant_id claim' } }];
}

// Campos obligatorios
const required = ['client_name', 'project_name', 'project_type'];
const missing = required.filter(f => !body[f] || body[f].toString().trim() === '');
if (missing.length > 0) {
  return [{ json: { _error: 'VALIDATION_MISSING_FIELDS', _status: 400, _details: 'Campos obligatorios faltantes: ' + missing.join(', '), _missing: missing } }];
}

// Validar project_type
const validTypes = ['reforma_integral', 'redistribucion', 'cambio_uso', 'adecuacion', 'apoyo_tecnico', 'otro'];
if (!validTypes.includes(body.project_type)) {
  return [{ json: { _error: 'VALIDATION_INVALID_TYPE', _status: 400, _details: 'project_type invalido. Valores permitidos: ' + validTypes.join(', '), _received: body.project_type } }];
}

const validUrgency = ['normal', 'alta', 'urgente'];
const urgency = body.urgency && validUrgency.includes(body.urgency) ? body.urgency : 'normal';

const validPropertyTypes = ['piso', 'casa', 'local', 'atico', 'bajo', 'duplex', 'otro'];
const propertyType = body.property_type && validPropertyTypes.includes(body.property_type) ? body.property_type : null;

// Validar email basico si viene
if (body.client_email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(body.client_email)) {
  return [{ json: { _error: 'VALIDATION_BAD_EMAIL', _status: 400, _details: 'Email cliente con formato invalido' } }];
}

return [{ json: {
  user_id: sess.user_id,
  tenant_id: sess.tenant_id,
  role: sess.role,
  request_id: sess.request_id,
  client_name: body.client_name.trim(),
  client_email: body.client_email ? body.client_email.trim() : null,
  client_phone: body.client_phone ? body.client_phone.trim() : null,
  project_name: body.project_name.trim(),
  project_type: body.project_type,
  location_address: body.location_address || null,
  location_city: body.location_city || null,
  location_province: body.location_province || null,
  property_type: propertyType,
  property_area_m2: body.property_area_m2 ? parseFloat(body.property_area_m2) : null,
  budget_target: body.budget_target ? parseFloat(body.budget_target) : null,
  budget_flexible: body.budget_flexible === true || body.budget_flexible === 'true',
  urgency: urgency,
  notes: body.notes ? body.notes.trim() : null
}}];

